const fs = await import('node:fs/promises');
const path = '/private/tmp/commonmark_0312.html';
const text = await fs.readFile(path, 'utf8');
const chars = Array.from(text).length;
const bytes = Buffer.byteLength(text, 'utf8');
const last50 = Array.from(text).slice(-50).join('');
const approxTokens = Math.round(chars / 4);
const endsWith = text.slice(-200);
const hasHtmlClose = /<\/html>\s*$/i.test(text);
const hasBodyClose = /<\/body>\s*<\/html>\s*$/i.test(text);
nodeRepl.write(JSON.stringify({chars, bytes, approxTokens, last50, hasHtmlClose, hasBodyClose, tailPreview: endsWith}, null, 2));
